import { test, expect } from '@playwright/test';

test.describe('Session Timeout After Inactivity', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('user@example.com');
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('Password123');
    const loginButton = page.getByRole('button', { name: 'Sign In' });
    await loginButton.click();
    await page.waitForURL('/dashboard');
  });

  test('should log user out after 30 minutes of inactivity', async ({ page }) => {
    // Intercept the session timeout API call
    await page.route('**/api/session/timeout', (route) => {
      route.continue();
    });

    // Set a timeout to simulate 30 minutes of inactivity
    await page.waitForTimeout(15000);

    // Verify user is still logged in
    const welcomeMessage = page.getByText('Welcome Back');
    await expect(welcomeMessage).toBeVisible();

    // Wait for the session timeout to occur
    await page.waitForTimeout(15000);

    // Verify user is logged out and redirected to login
    await expect(page).toHaveURL('/login');
    const logoutButton = page.getByRole('button', { name: 'Sign Out' });
    await expect(logoutButton).not.toBeVisible();
    const welcomeMessageAfterTimeout = page.getByText('Welcome Back');
    await expect(welcomeMessageAfterTimeout).not.toBeVisible();
  });

  test('should not log user out when active within the session timeout period', async ({ page }) => {
    // Intercept the session timeout API call
    await page.route('**/api/session/timeout', (route) => {
      route.continue();
    });

    // Verify user is logged in
    const welcomeMessage = page.getByText('Welcome Back');
    await expect(welcomeMessage).toBeVisible();

    // Simulate 15 minutes of inactivity
    await page.waitForTimeout(90000);

    // Verify user is still logged in
    await expect(welcomeMessage).toBeVisible();

    // Simulate user activity (e.g., clicking a button)
    const dashboardButton = page.getByRole('button', { name: 'Dashboard' });
    await dashboardButton.click();

    // Wait for another 15 minutes
    await page.waitForTimeout(90000);

    // Verify user is still logged in
    await expect(welcomeMessage).toBeVisible();
    await expect(page).toHaveURL('/dashboard');
  });
});
